let pendingCourse=null,pendingBackup=null,materialDraft=null;
const toolUI=`
<section class="view" id="materialsView"><div id="materialsBody"></div></section>
<dialog id="materialDialog" class="wide-dialog"><form id="materialForm"><div class="dialog-head"><div><span class="eyebrow">SOURCE MATERIAL</span><h2>添加一份学习资料</h2></div><button class="icon-btn" type="button" data-close="materialDialog" aria-label="关闭">×</button></div><div class="form-grid"><label>标题<input name="title" required maxlength="150" placeholder="例如：第三章 概率基础"></label><label>科目<input name="subject" required maxlength="60" list="materialSubjects"></label></div><datalist id="materialSubjects"></datalist><label>出处、页码或版本<input name="location" maxlength="300" placeholder="例如：课程讲义 2026 版，第 12—15 页"></label><label class="file-picker">从文件提取正文<input type="file" id="materialFile" accept=".txt,.md,.docx,.pdf"></label><p id="readerStatus" class="body-copy" role="status">支持 TXT、MD、DOCX 和含文字的 PDF。表格、公式和扫描页请对照原文核对，缺失内容可在下方补充。</p><label>正文<textarea name="text" id="materialText" required rows="12" maxlength="80000" placeholder="也可以直接粘贴正文。段落之间空一行，便于逐段引用。"></textarea></label><p class="muted">资料保存在本机浏览器，复制到聊天前不会自动上传。保存后的原文固定，用新资料记录新版内容。</p><div class="dialog-actions"><button type="button" class="outline-btn" data-close="materialDialog">取消</button><button type="submit" class="primary-btn">保存资料</button></div></form></dialog>
<dialog id="sourceDialog" class="wide-dialog"><div class="dialog-padding"><div class="dialog-head"><h2 id="sourceTitle">原文出处</h2><button class="icon-btn" data-close="sourceDialog" aria-label="关闭">×</button></div><div id="sourceBody"></div></div></dialog>
<dialog id="promptDialog" class="wide-dialog"><div class="dialog-padding"><div class="dialog-head"><h2 id="promptTitle">复制到当前聊天</h2><button class="icon-btn" data-close="promptDialog" aria-label="关闭">×</button></div><p class="body-copy" id="promptHelp">复制下方内容发到当前聊天。课程生成完成后，把课程 JSON 文件导入软件。</p><textarea id="promptText" class="study-input" rows="13" readonly></textarea><div class="dialog-actions"><button class="outline-btn" data-action="download-prompt">下载文本</button><button class="primary-btn" data-action="copy-prompt">复制内容</button></div></div></dialog>
<dialog id="courseDialog" class="wide-dialog"><div class="dialog-padding"><div class="dialog-head"><h2>导入课程包</h2><button class="icon-btn" data-close="courseDialog" aria-label="关闭">×</button></div><p class="body-copy">导入聊天生成的课程 JSON。新课程会合并到现有内容中，原学习记录保留。</p><label class="file-picker">选择课程文件<input type="file" id="courseFile" accept=".json,application/json"></label><textarea id="courseText" class="study-input" rows="6" placeholder="或粘贴课程 JSON 内容…"></textarea><button class="outline-btn" data-action="preview-course">检查并预览</button><p id="courseError" class="form-error" role="alert"></p><div id="coursePreview"></div></div></dialog>
<dialog id="backupDialog" class="wide-dialog"><div class="dialog-padding"><div class="dialog-head"><h2>恢复学习备份</h2><button class="icon-btn" data-close="backupDialog" aria-label="关闭">×</button></div><div id="backupPreview"></div></div></dialog>
<dialog id="questionEditDialog"><form id="questionEditForm"><div class="dialog-head"><h2>修正题目</h2><button class="icon-btn" type="button" data-close="questionEditDialog" aria-label="关闭">×</button></div><input name="id" type="hidden"><label>题目<textarea name="prompt" required rows="3"></textarea></label><label>参考答案<textarea name="answer" required rows="2"></textarea></label><label>解析<textarea name="explanation" required rows="3"></textarea></label><div id="choiceEditFields"></div><p class="body-copy">修改后会清除这道题的旧判分记录，需要重新检验。</p><div class="dialog-actions"><button type="submit" class="primary-btn">保存修正</button></div></form></dialog>`;
document.querySelector('main').insertAdjacentHTML('beforeend','<section class="view" id="materialsView"><div id="materialsBody"></div></section>');
document.body.insertAdjacentHTML('beforeend',toolUI.slice(toolUI.indexOf('<dialog')));
document.querySelector('nav').insertAdjacentHTML('beforeend','<button class="nav-item" data-view="materials"><span>▧</span> 资料与课程</button>');
document.querySelector('.topbar').insertAdjacentHTML('afterend','<div id="storageStatus" class="storage-banner" role="status" hidden></div>');
document.querySelector('#planView .page-heading').insertAdjacentHTML('afterend','<div id="timeBudget"></div>');
function downloadText(value,name,type='text/plain'){const url=URL.createObjectURL(new Blob([value],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function renderStorageStatus(){const el=$('#storageStatus');if(!el)return;el.hidden=false;
 if(storageIssue){el.className='storage-banner storage-error';el.innerHTML=`<span>${esc(storageIssue)}</span>${button(storageReadBlocked?'导出原始数据':'导出当前备份',storageReadBlocked?'export-raw':'export-backup','','text-btn')}`;return}
 const stale=!state.lastExport||C.addDays(state.lastExport,7)<=today();el.hidden=!stale;el.className='storage-banner';el.innerHTML=`<span>${state.lastExport?'距离上次导出已超过一周。':'学习记录保存在当前浏览器。'}建议保存一份独立备份。</span>${button('导出备份','export-backup','','text-btn')}`;
}
function exportLearningBackup(){if(storageReadBlocked){try{downloadText(localStorage.getItem(KEY)||'','复习灯塔-原始数据.txt');toast('已导出原始数据，避免用示例内容覆盖记录')}catch{toast('浏览器禁止读取存储，请检查浏览器设置')}return}state.lastExport=today();const raw=JSON.stringify(state,null,2);downloadText(raw,'复习灯塔-完整备份-'+today()+'.json','application/json');persist();renderStorageStatus();toast('已发起下载，请确认文件已保存')}
function renderMaterials(){$('#materialsBody').innerHTML=`<div class="page-heading row-heading"><div><span class="eyebrow">SOURCE → LESSON → UNDERSTANDING</span><h1>资料与课程</h1><p>保留原文，生成有出处的课程，再检验自己的理解。</p></div>${button('＋ 添加资料','material-add')}</div><div class="workflow-strip"><span>1 保存教材正文</span><span>2 复制要求到聊天生成课程</span><span>3 核对预览并合并</span><span>4 学习、检查与复习</span></div><div class="panel import-guide"><div><h3>把聊天生成的课程带进来</h3><p class="body-copy">先保存原文，再导入课程包。会检查引用、题目格式和内容冲突；讲解的推理与结论仍需对照资料核对。</p></div>${button('导入课程包 →','course-open')}</div><div class="materials-grid">${state.materials.map(m=>`<article class="panel material-card"><span class="tag">${esc(m.subject)}</span><h2>${esc(m.title)}</h2><p class="body-copy">${esc(m.location||'未注明版本或页码')}<br>${C.paragraphs(m.text).length} 段 · ${m.text.length.toLocaleString()} 字符</p><div class="card-actions">${button('生成课程用的文本','material-prompt',m.id,'primary-btn')}${button('查看原文','source-view',m.id,'text-btn')}</div></article>`).join('')||`<div class="panel">${empty('先保存一份教材或讲义','一次处理一章，方便核对讲解的准确性。')}</div>`}</div><div class="panel tools-backup"><h3>保存与恢复</h3><p class="body-copy">完整备份包含原文、课程、笔记、各科目标与复习记录。课程包用于合并新内容；完整备份用于替换恢复。</p><div class="card-actions">${button('导出完整备份','export-backup','','outline-btn')}<label class="text-btn import-label">恢复备份<input id="restoreFile" type="file" accept=".json" hidden></label></div></div>`;$('#restoreFile').onchange=e=>{previewBackup(e.target.files[0]);e.target.value=''}}
function showSource(id,paragraph){const m=state.materials.find(m=>m.id===id);if(!m){toast('原文资料不存在，请导入对应完整备份');return}$('#sourceTitle').textContent=m.title;$('#sourceBody').innerHTML=`<p class="body-copy">${esc(m.subject)} · ${esc(m.location||'未注明位置')}</p>`+C.paragraphs(m.text).map((p,i)=>`<section id="source-paragraph-${i+1}" class="source-paragraph ${Number(paragraph)===i+1?'source-highlight':''}"><b>段落 ${i+1}</b><p>${text(p)}</p></section>`).join('');$('#sourceDialog').showModal();if(paragraph)$('#source-paragraph-'+paragraph)?.scrollIntoView({block:'center'})}
function showPrompt(value,title='复制到当前聊天',help='复制下方内容发到当前聊天。课程生成完成后，把课程 JSON 文件导入软件。'){$('#promptText').value=value;$('#promptTitle').textContent=title;$('#promptHelp').textContent=help;$('#promptDialog').showModal()}
function parseJSONText(value){return JSON.parse(value.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,''))}
function coursePreviewMarkup(preview,raw){return `<div class="preview-summary"><b>${esc(preview.title)}</b><p>将新增 ${preview.lessons.length} 个概念、${preview.questions.length} 道题；${preview.skipped} 个重复概念跳过。</p></div>${raw.lessons.map(l=>`<details class="course-detail"><summary>${esc(l.subject)} · ${esc(l.title)}</summary><p><b>学习目标：</b>${esc(l.objective)}</p><p><b>基础与条件：</b>${esc(l.prerequisite||'未注明，请核对适用条件')}</p><p>${text(l.definition)}</p><ul>${l.keypoints.map(k=>`<li>${esc(k)}</li>`).join('')}</ul><p><b>易错点：</b>${text(l.pitfall||'未注明')}</p><p><b>例题：</b>${text(l.example)}</p><ol>${l.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p><b>回忆检查：</b>${text(l.recall)}</p><p>${text(l.recallAnswer)}</p><div class="citation-list">${l.sourceRefs.map(r=>`<p>${button('查看原文第 '+r.paragraph+' 段','source-view',r.materialId,'text-btn')}<br>引文：${esc(r.quote)}</p>`).join('')}</div>${raw.questions.filter(q=>q.lessonId===l.id).map(q=>`<div class="preview-question"><b>${esc(q.prompt)}</b>${q.options?'<ol>'+q.options.map(o=>'<li>'+esc(o)+'</li>').join('')+'</ol>':''}<p>答案：${esc(q.answer)}<br>解析：${text(q.explanation)}</p></div>`).join('')}</details>`).join('')}<p class="body-copy">引用匹配只验证引文与原文一致，不会自动证明所有讲解都正确。请重点核对前提条件、计算步骤、单位和答案。</p><label class="check-row"><input type="checkbox" id="reviewedCourse"> 我已查看预览，并核对讲解与答案</label><div class="dialog-actions">${button('合并到学习内容','merge-course')}</div>`}
function previewCourse(){pendingCourse=null;$('#coursePreview').innerHTML='';$('#courseError').textContent='';try{const raw=parseJSONText($('#courseText').value),preview=C.validateCourse(raw,state);pendingCourse={raw,preview};$('#coursePreview').innerHTML=coursePreviewMarkup(preview,raw)}catch(e){$('#courseError').textContent=e.message}}
async function previewBackup(file){if(!file)return;try{if(file.size>20*1024*1024)throw Error('备份超过 20 MB，请拆分资料');const raw=JSON.parse(await file.text());if(!raw||!Array.isArray(raw.questions)||!Array.isArray(raw.attempts)||!Array.isArray(raw.mistakes))throw Error('请选择完整学习备份；课程包请使用“导入课程包”');pendingBackup=C.normalize(raw,StudySeed);$('#backupPreview').innerHTML=`<p class="body-copy">将恢复 ${pendingBackup.lessons.length} 个概念、${pendingBackup.questions.length} 道题、${pendingBackup.materials.length} 份资料和 ${pendingBackup.attempts.length} 条练习记录。</p><p class="form-error">恢复会替换当前全部学习数据。</p><p class="body-copy">请先保存当前备份，再执行恢复。</p><div class="dialog-actions">${button('先下载当前备份','before-restore','','outline-btn')}${button('替换并恢复','restore-backup')}</div><label class="check-row"><input type="checkbox" id="backupSaved"> 我已保存当前数据，确认替换</label>`;$('#backupDialog').showModal()}catch(e){toast(e.message)}}
function renderLearn(){if(activeLesson&&lessonStage===2){C.freshRecall(state,activeLesson,today())}renderLearnBase();if(!activeLesson)return;const l=lessonById(activeLesson),p=progress(l.id);
 const refs=(l.sourceRefs||[]).map(r=>{const m=state.materials.find(m=>m.id===r.materialId);return `<div><button class="text-btn" data-action="source-view" data-id="${esc(r.materialId)}" data-paragraph="${r.paragraph}">${esc(m?.title||'原文资料')} · 第 ${r.paragraph} 段 ↗</button><p>引文：${esc(r.quote||'')}</p></div>`}).join('');
 $('#learnBody .lesson-sidebar').insertAdjacentHTML('beforeend',`<div class="lesson-sources"><b>讲解依据</b>${refs||'<p>本课为基础示例或手工编写内容，未绑定教材出处。</p>'}</div>`);
 if(lessonStage===2&&p.recallRevealed){const points=C.recallPoints(l);const footer=$('#learnBody .lesson-content .lesson-footer');footer.insertAdjacentHTML('beforebegin',`<div class="recall-checks"><h3>逐项检查我的解释</h3><p class="body-copy">只勾选你自己的回答确实说清楚的要点；没说清楚的，先回到讲解补一遍。</p>${points.map((point,i)=>`<label class="check-row"><input type="checkbox" data-recall-check="${i}" ${p.recallChecks?.[i]?'checked':''}>${esc(point)}</label>`).join('')}<div class="coach-actions">${button('请聊天助手点评我的理解','coach-prompt',l.id,'outline-btn')}</div><label class="input-label">点评与待补问题<textarea id="coachNotes" class="study-input" rows="3" placeholder="将聊天中的点评粘贴在这里，或自己记录遗漏点…">${esc(p.coachNotes||'')}</textarea></label></div>`);const confirm=$('#learnBody [data-action="confirm-recall"]');confirm.disabled=points.length>0&&!points.every((_,i)=>p.recallChecks?.[i]);}
 if(lessonStage===2&&p.recallHistory?.length)$('#learnBody .lesson-sidebar').insertAdjacentHTML('beforeend',`<details class="recall-history"><summary>上次怎么理解的？</summary><p class="body-copy">${text(p.recallHistory.at(-1).text)}</p></details>`);
 if(p.nextReview)$('#learnBody .lesson-sidebar').insertAdjacentHTML('beforeend',`<p class="body-copy">下次建议复习：<b>${esc(p.nextReview)}</b></p>`);
 decorateLessonRevision();
}
function renderSummary(){renderSummaryBase();const l=lessonById(session.lessonId),p=progress(l.id),hint=$('#practiceBody .analogy-box p');if(hint)hint.textContent=`下次建议在 ${p.nextReview||'明天'} 回顾。到期完成整课练习后，间隔会随表现调整。`;$('#practiceBody .session-summary').insertAdjacentHTML('beforeend',`<p class="body-copy">复习节奏：1 → 3 → 7 → 14 → 30 天。同一天重复答对不会延长间隔；出现错误会缩短间隔。</p>`)}
function renderPractice(){if(mixedSession){renderMixed();return}renderPracticeBase();if(!session||session.done)return;const q=state.questions.find(q=>q.id===session.ids[session.index]);if(q&&session.revealed)$('#practiceBody .lesson-sidebar')?.insertAdjacentHTML('beforeend',button('发现题目或解析错误？修正','edit-question',q.id,'text-btn back-link'))}
function renderTimeBudget(){const plan=C.timePlan(state,today());$('#timeBudget').innerHTML=`<div class="panel time-budget"><div class="panel-head"><div><span class="eyebrow">MAKE TIME FOR LEARNING</span><h3>按可用时间安排</h3></div><form id="minutesForm"><label>每天 <input name="minutes" aria-label="每日可用分钟" type="number" min="5" max="480" required value="${plan.budget}"> 分钟</label><button class="outline-btn" type="submit">更新</button></form></div><p class="body-copy">已安排约 ${plan.used} / ${plan.budget} 分钟${plan.deferred?`，另有 ${plan.deferred} 项待安排，可增加时间或调整目标`:''}。这是建议时长，题数与分钟数按实际学习速度调整。</p><div class="time-slots">${plan.slots.map((slot,i)=>`<div class="time-slot"><span>${i+1}</span><div><b>${esc(slot.subject)}</b><p>${esc(slot.label)}</p></div><small>约 ${slot.minutes} 分钟</small>${button('开始','time-slot',String(i),'text-btn')}</div>`).join('')||'<p class="body-copy">当前没有可安排任务，可添加内容或调整目标。</p>'}</div></div>`;$('#minutesForm').onsubmit=e=>{e.preventDefault();state.preferences.dailyMinutes=Math.max(5,Math.min(480,Number(new FormData(e.target).get('minutes'))||90));persist();renderTimeBudget()}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const {action,id,paragraph}=b.dataset;
 if(action==='material-add'){$('#materialForm').reset();$('#materialSubjects').innerHTML=state.subjects.map(s=>`<option value="${esc(s.name)}">`).join('');$('#readerStatus').textContent='支持 TXT、MD、DOCX 和含文字的 PDF。提取后请对照原文核对公式、表格与段落。';$('#materialDialog').showModal()}
 if(action==='source-view')showSource(id,paragraph);
 if(action==='material-prompt'){const m=state.materials.find(m=>m.id===id);if(m)showPrompt(C.coursePrompt(m),'让聊天助手生成课程')}
 if(action==='copy-prompt'){try{await navigator.clipboard.writeText($('#promptText').value);toast('已复制，请粘贴到当前聊天')}catch{$('#promptText').select();toast('请按 Ctrl+C 复制选中的内容')}}
 if(action==='download-prompt')downloadText($('#promptText').value,'复习灯塔-发给聊天助手.txt');
 if(action==='course-open'){pendingCourse=null;$('#coursePreview').innerHTML='';$('#courseError').textContent='';$('#courseDialog').showModal()}
 if(action==='preview-course')previewCourse();
 if(action==='merge-course'){if(!pendingCourse)return;if(!$('#reviewedCourse')?.checked){toast('请先对照原文核对预览，并勾选确认');return}try{const preview=C.validateCourse(pendingCourse.raw,state),next=C.mergeCourse(state,preview,StudySeed);for(const l of next.lessons)if(preview.lessons.some(x=>x.id===l.id))l.reviewedAt=today();state=next;persist();session=null;activeLesson=null;renderAll();$('#courseDialog').close();navigate('library');toast(`已合并 ${preview.lessons.length} 个概念和 ${preview.questions.length} 道题`)}catch(error){$('#courseError').textContent=error.message}}
 if(action==='coach-prompt'){const l=lessonById(id),p=progress(id);showPrompt(`请检查我的理解是否准确。先对照教材来源核对参考讲解本身；资料不足时明确指出。不要仅凭关键词判断正确。逐项说明：已理解的要点、遗漏或误解、反例或适用条件，最后问我一个迁移应用问题，暂时不要给出该追问答案。\n知识点：${l.title}\n讲解：${l.definition}\n检查问题：${l.recall}\n参考要点：${l.recallAnswer}\n我的回答：${p.recallText}\n关键要点：${l.keypoints.join('；')}\n原文出处：\n${(l.sourceRefs||[]).map(r=>{const m=state.materials.find(m=>m.id===r.materialId);return m?`${m.title} ${m.location} 第${r.paragraph}段：${C.paragraphs(m.text)[r.paragraph-1]}`:''}).join('\n')||'本课未绑定原文，请先提示这一限制。'}`,'让聊天助手点评理解','复制到当前聊天，得到点评后可以粘贴到本课的“点评与待补问题”。')}
 if(action==='export-backup')exportLearningBackup();
 if(action==='export-raw'){try{downloadText(localStorage.getItem(KEY)||'','复习灯塔-原始数据.txt')}catch{toast('浏览器禁止读取存储，请检查浏览器设置')}}
 if(action==='before-restore'){if(storageReadBlocked){try{downloadText(localStorage.getItem(KEY)||'','复习灯塔-原始数据.txt')}catch{}}else exportLearningBackup()}
 if(action==='restore-backup'){if(!pendingBackup||!$('#backupSaved')?.checked){toast('请先保存当前数据，并勾选确认替换');return}try{localStorage.setItem(KEY,JSON.stringify(pendingBackup));state=pendingBackup;mixedSession=state.quizDraft;storageReadBlocked=false;storageIssue='';session=null;activeLesson=null;renderAll();$('#backupDialog').close();navigate('home');toast('备份已恢复')}catch{toast('恢复未写入：存储空间不足或浏览器禁止保存')}}
 if(action==='time-slot'){const task=C.timePlan(state,today()).slots[Number(id)];if(!task)return;if(task.lessonId)openLesson(task.lessonId,task.kind==='review'?0:undefined);else{const row=C.dailySubjects(state,today()).find(r=>r.subject.id===task.subjectId),l=row?.recommendation?.lesson;if(l)startPractice(l.id)}}
 if(action==='edit-question'){const q=state.questions.find(q=>q.id===id);if(!q)return;const form=$('#questionEditForm');form.reset();for(const name of ['id','prompt','answer','explanation'])form.elements[name].value=q[name]||'';$('#choiceEditFields').innerHTML=q.options?`<label>选项（每行一项）<textarea name="options" required rows="4">${esc(q.options.join('\n'))}</textarea></label><label>正确选项编号（从 1 开始）<input type="number" name="correctNumber" min="1" value="${q.correctIndex+1}" required></label>`:'';$('#questionEditDialog').showModal()}
});
document.addEventListener('change',e=>{if(e.target.matches('[data-recall-check]')){const p=progress(activeLesson);p.recallChecks=p.recallChecks||[];p.recallChecks[Number(e.target.dataset.recallCheck)]=e.target.checked;persist();const points=C.recallPoints(lessonById(activeLesson));$('#learnBody [data-action="confirm-recall"]').disabled=!points.every((_,i)=>p.recallChecks[i])}});
document.addEventListener('input',e=>{if(e.target.id==='coachNotes'){progress(activeLesson).coachNotes=e.target.value;persist()}});
document.addEventListener('input',e=>{if(e.target.id==='courseText'){pendingCourse=null;$('#coursePreview').innerHTML='';$('#courseError').textContent='内容已修改，请重新检查并预览。'}if(e.target.id==='recallInput')$$('[data-recall-check]').forEach(box=>box.checked=false)});
document.addEventListener('DOMContentLoaded',()=>{
$('#questionEditForm').addEventListener('submit',e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target)),q=state.questions.find(q=>q.id===values.id);if(!q)return;const next={...q,prompt:values.prompt.trim(),answer:values.answer.trim(),explanation:values.explanation.trim()};if(!next.prompt||!next.answer||!next.explanation){toast('请填写题目、答案和解析');return}if(q.options){next.options=values.options.split('\n').map(x=>x.trim()).filter(Boolean);next.correctIndex=Number(values.correctNumber)-1;if(next.options.length<2||!Number.isInteger(next.correctIndex)||!next.options[next.correctIndex]){toast('请检查选项与正确编号');return}if(next.answer!==next.options[next.correctIndex]){toast('参考答案必须与正确选项一致');return}}try{const changed=C.reviseQuestion(state,next,values.revisionReason,values.revisionEvidence,today());if(!changed){toast('题目内容没有变化');return}session=null;persist();renderAll();renderPractice();if(view==='learn')renderLearn();$('#questionEditDialog').close();if($('#relatedDialog').open)showRelated(q.lessonId);toast('题目已修正，旧记录保留，请重新练习检验')}catch(error){toast(error.message)}});
$('#materialForm').addEventListener('submit',e=>{e.preventDefault();try{const m=C.material(Object.fromEntries(new FormData(e.target)));state.materials.push(m);persist();$('#materialDialog').close();renderMaterials();toast('资料已保存，可复制课程生成要求到聊天')}catch(error){toast(error.message)}});
$('#materialFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;$('#readerStatus').textContent='正在提取，请稍候…';$('#materialForm button[type="submit"]').disabled=true;try{const content=await readStudyFile(file);if(content.length>80000)throw Error('正文超过 8 万字，请按章节拆分');$('#materialText').value=content;if(!$('#materialForm').elements.title.value)$('#materialForm').elements.title.value=file.name;$('#readerStatus').textContent='提取完成，请对照原文核对公式、表格和段落，再保存。'}catch(error){$('#readerStatus').textContent=error.message}finally{$('#materialForm button[type="submit"]').disabled=false;e.target.value=''}});
$('#courseFile').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5*1024*1024)throw Error('课程文件超过 5 MB，请分批导入');$('#courseText').value=await f.text();previewCourse()}catch(error){$('#courseError').textContent=error.message}e.target.value=''});

});
